begin;

-- Catálogo legal versionado. Os limites são vinculados ao contexto de aplicação
-- da norma (classe da água, tipo de lançamento etc.), não apenas à legislação.
alter table public.legislacao
  add column if not exists orgao_emissor text,
  add column if not exists fonte_url text,
  add column if not exists observacao text;

update public.legislacao
set orgao_emissor = 'Ministério da Saúde',
    fonte_url = 'https://bvsms.saude.gov.br/bvs/saudelegis/gm/2021/prt0888_24_05_2021_rep.html',
    observacao = 'Anexo XX da Portaria de Consolidação GM/MS nº 5/2017, alterado pelas Portarias GM/MS nº 888/2021 e nº 2.472/2021.'
where lower(sigla) = lower('Portaria 888/2021');

update public.legislacao
set orgao_emissor = 'Conselho Nacional do Meio Ambiente (CONAMA)',
    fonte_url = 'https://www.ana.gov.br/portalpnqa/Publicacao/RESOLUCAO_CONAMA_n_357.pdf',
    observacao = 'Classificação dos corpos de água e padrões de qualidade por classe e salinidade.'
where lower(sigla) = lower('CONAMA nº 357/2005');

update public.legislacao
set orgao_emissor = 'Conselho Nacional do Meio Ambiente (CONAMA)',
    fonte_url = 'https://conama.mma.gov.br/?id=627&option=com_sisconama&task=arquivo.download',
    observacao = 'Condições e padrões de lançamento de efluentes; exigências locais e do licenciamento podem ser mais restritivas.'
where lower(sigla) = lower('CONAMA nº 430/2011');

create table if not exists public.legislacao_contexto (
  id integer generated by default as identity primary key,
  legislacao_id integer not null references public.legislacao(id) on update cascade on delete cascade,
  matriz_id integer not null references public.matriz(id) on update cascade on delete restrict,
  codigo text not null unique,
  nome text not null,
  descricao text,
  referencia_legal text not null,
  ordem integer not null default 0,
  ativo boolean not null default true,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create unique index if not exists legislacao_contexto_nome_uidx
  on public.legislacao_contexto (legislacao_id, matriz_id, lower(nome));
create index if not exists legislacao_contexto_filtro_idx
  on public.legislacao_contexto (matriz_id, legislacao_id, ativo, ordem);

drop trigger if exists set_legislacao_contexto_updated_at on public.legislacao_contexto;
create trigger set_legislacao_contexto_updated_at
before update on public.legislacao_contexto
for each row execute function public.set_updated_at();

insert into public.legislacao_contexto
  (legislacao_id, matriz_id, codigo, nome, descricao, referencia_legal, ordem)
select l.id, m.id, v.codigo, v.nome, v.descricao, v.referencia, v.ordem
from (values
  ('Portaria 888/2021', 'Água', 'P888_POTABILIDADE', 'Água para consumo humano — padrão de potabilidade', 'Padrões microbiológicos, substâncias químicas, cianotoxinas e padrão organoléptico.', 'Anexo XX; arts. 27 a 42; Anexos 1, 9, 10 e 11', 10),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_DOCE_1', 'Água doce — Classe 1', 'Águas doces enquadradas na classe 1.', 'Arts. 14 e 15; Tabela I', 20),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_DOCE_1_AQUICULTURA', 'Água doce — Classe 1 (pesca/cultivo para consumo intensivo)', 'Aplicam-se os padrões da classe 1 e as substituições adicionais para pesca ou cultivo destinado ao consumo intensivo.', 'Art. 14, III; Tabela II', 21),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_DOCE_2', 'Água doce — Classe 2', 'Padrões da classe 1, exceto as condições e os limites específicos da classe 2.', 'Art. 15', 22),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_DOCE_3', 'Água doce — Classe 3', 'Águas doces enquadradas na classe 3.', 'Art. 16; Tabela III', 23),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_DOCE_4', 'Água doce — Classe 4', 'Águas doces enquadradas na classe 4.', 'Art. 17', 24),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_SALINA_1', 'Água salina — Classe 1', 'Águas salinas enquadradas na classe 1.', 'Art. 18; Tabela IV', 30),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_SALINA_1_AQUICULTURA', 'Água salina — Classe 1 (pesca/cultivo para consumo intensivo)', 'Padrões da classe 1 com substituições adicionais para pesca ou cultivo destinado ao consumo intensivo.', 'Art. 18, III; Tabela V', 31),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_SALINA_2', 'Água salina — Classe 2', 'Padrões da classe 1, exceto as condições e os limites específicos da classe 2.', 'Art. 19; Tabela VI', 32),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_SALINA_3', 'Água salina — Classe 3', 'Águas salinas enquadradas na classe 3.', 'Art. 20', 33),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_SALOBRA_1', 'Água salobra — Classe 1', 'Águas salobras enquadradas na classe 1.', 'Art. 21; Tabela VII', 40),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_SALOBRA_1_AQUICULTURA', 'Água salobra — Classe 1 (pesca/cultivo para consumo intensivo)', 'Padrões da classe 1 com substituições adicionais para pesca ou cultivo destinado ao consumo intensivo.', 'Art. 21, III; Tabela VIII', 41),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_SALOBRA_2', 'Água salobra — Classe 2', 'Padrões da classe 1, exceto as condições e os limites específicos da classe 2.', 'Art. 22; Tabela IX', 42),
  ('CONAMA nº 357/2005', 'Água Bruta', 'C357_SALOBRA_3', 'Água salobra — Classe 3', 'Águas salobras enquadradas na classe 3.', 'Art. 23', 43),
  ('CONAMA nº 430/2011', 'Efluente', 'C430_GERAL', 'Efluentes — lançamento geral', 'Condições e padrões gerais para lançamento direto de efluentes.', 'Art. 16; Tabela I', 50),
  ('CONAMA nº 430/2011', 'Efluente', 'C430_ESGOTO_SANITARIO', 'Esgotos sanitários — lançamento direto', 'Condições e padrões específicos para lançamento direto de efluentes oriundos de sistemas de tratamento de esgotos sanitários.', 'Arts. 21 e 21-A', 51),
  ('CONAMA nº 430/2011', 'Efluente', 'C430_EMISSARIO_SUBMARINO', 'Esgotos sanitários — emissário submarino', 'Condições aplicáveis ao lançamento de efluentes de sistemas de tratamento de esgotos sanitários por meio de emissários submarinos.', 'Art. 22', 52)
) as v(sigla, matriz, codigo, nome, descricao, referencia, ordem)
join public.legislacao l on lower(l.sigla) = lower(v.sigla)
join public.matriz m on lower(m.nome) = lower(v.matriz)
on conflict (codigo) do update
set nome = excluded.nome,
    descricao = excluded.descricao,
    referencia_legal = excluded.referencia_legal,
    ordem = excluded.ordem,
    ativo = true;

alter table public.parametro
  add column if not exists contexto_legislacao_id integer references public.legislacao_contexto(id) on update cascade on delete restrict,
  add column if not exists categoria text not null default 'Outros',
  add column if not exists tipo_resultado text not null default 'numerico',
  add column if not exists tipo_limite text not null default 'maximo',
  add column if not exists criterio_texto text,
  add column if not exists fonte_referencia text,
  add column if not exists ordem integer not null default 0,
  add column if not exists ativo boolean not null default true;

alter table public.parametro drop constraint if exists parametro_tipo_resultado_check;
alter table public.parametro add constraint parametro_tipo_resultado_check
  check (tipo_resultado in ('numerico', 'qualitativo'));
alter table public.parametro drop constraint if exists parametro_tipo_limite_check;
alter table public.parametro add constraint parametro_tipo_limite_check
  check (tipo_limite in ('maximo', 'minimo', 'faixa', 'ausencia', 'informativo'));

drop index if exists public.parametro_contexto_uidx;
create unique index if not exists parametro_contexto_legal_uidx
  on public.parametro (lower(nome), contexto_legislacao_id)
  where contexto_legislacao_id is not null;
create index if not exists parametro_contexto_legal_idx
  on public.parametro (contexto_legislacao_id, ativo, categoria, ordem, nome);

alter table public.resultado_analise
  alter column valor_medido drop not null,
  add column if not exists valor_qualitativo text,
  add column if not exists contexto_legislacao_id integer references public.legislacao_contexto(id) on update cascade on delete restrict,
  add column if not exists limite_minimo_aplicado numeric(18, 6),
  add column if not exists limite_maximo_aplicado numeric(18, 6),
  add column if not exists tipo_limite_aplicado text,
  add column if not exists criterio_legal_aplicado text,
  add column if not exists fonte_legal_aplicada text;

alter table public.resultado_analise drop constraint if exists resultado_analise_valor_medido_check;
alter table public.resultado_analise drop constraint if exists resultado_valor_preenchido_check;
alter table public.resultado_analise add constraint resultado_valor_preenchido_check
  check (
    (valor_medido is not null and valor_medido >= 0 and valor_qualitativo is null)
    or (valor_medido is null and nullif(trim(valor_qualitativo), '') is not null)
  );

create index if not exists resultado_contexto_idx
  on public.resultado_analise (contexto_legislacao_id, datacoleta desc);

-- Funções temporárias tornam o catálogo legível e permitem repetir a migration
-- com segurança sem deixar funções auxiliares no schema público.
create or replace function pg_temp.add_legal_params(p_contexto text, p_dados jsonb)
returns void
language sql
as $$
  insert into public.parametro (
    nome, unidade_medida, valor_parametro, limite_minimo, limite_maximo,
    matriz_id, legislacao_id, contexto_legislacao_id, categoria,
    tipo_resultado, tipo_limite, criterio_texto, fonte_referencia, ordem, ativo
  )
  select
    d.nome,
    coalesce(d.unidade, ''),
    null,
    d.minimo,
    d.maximo,
    c.matriz_id,
    c.legislacao_id,
    c.id,
    coalesce(d.categoria, 'Outros'),
    coalesce(d.tipo_resultado, 'numerico'),
    coalesce(d.tipo_limite,
      case when d.minimo is not null and d.maximo is not null then 'faixa'
           when d.minimo is not null then 'minimo'
           when d.maximo is not null then 'maximo'
           else 'informativo' end),
    d.criterio,
    coalesce(d.referencia, c.referencia_legal),
    coalesce(d.ordem, 0),
    true
  from public.legislacao_contexto c
  cross join jsonb_to_recordset(p_dados) as d(
    nome text, unidade text, minimo numeric, maximo numeric, categoria text,
    tipo_resultado text, tipo_limite text, criterio text, referencia text, ordem integer
  )
  where c.codigo = p_contexto
  on conflict (lower(nome), contexto_legislacao_id)
    where contexto_legislacao_id is not null
  do update set
    unidade_medida = excluded.unidade_medida,
    limite_minimo = excluded.limite_minimo,
    limite_maximo = excluded.limite_maximo,
    matriz_id = excluded.matriz_id,
    legislacao_id = excluded.legislacao_id,
    categoria = excluded.categoria,
    tipo_resultado = excluded.tipo_resultado,
    tipo_limite = excluded.tipo_limite,
    criterio_texto = excluded.criterio_texto,
    fonte_referencia = excluded.fonte_referencia,
    ordem = excluded.ordem,
    ativo = true;
$$;

create or replace function pg_temp.clone_legal_params(p_origem text, p_destino text)
returns void
language sql
as $$
  insert into public.parametro (
    nome, unidade_medida, valor_parametro, limite_minimo, limite_maximo,
    matriz_id, legislacao_id, contexto_legislacao_id, categoria,
    tipo_resultado, tipo_limite, criterio_texto, fonte_referencia, ordem, ativo
  )
  select
    p.nome, p.unidade_medida, null, p.limite_minimo, p.limite_maximo,
    destino.matriz_id, destino.legislacao_id, destino.id, p.categoria,
    p.tipo_resultado, p.tipo_limite, p.criterio_texto,
    destino.referencia_legal, p.ordem, true
  from public.parametro p
  join public.legislacao_contexto origem on origem.id = p.contexto_legislacao_id
  cross join public.legislacao_contexto destino
  where origem.codigo = p_origem and destino.codigo = p_destino
  on conflict (lower(nome), contexto_legislacao_id)
    where contexto_legislacao_id is not null
  do nothing;
$$;

