-- Algumas classes herdam integralmente a classe anterior, com as exceções
-- já registradas acima. Esta etapa final materializa os itens herdados sem
-- sobrescrever os limites específicos de cada contexto.
select pg_temp.clone_legal_params('C357_DOCE_1', 'C357_DOCE_1_AQUICULTURA');
select pg_temp.clone_legal_params('C357_DOCE_1', 'C357_DOCE_2');
select pg_temp.clone_legal_params('C357_SALINA_1', 'C357_SALINA_1_AQUICULTURA');
select pg_temp.clone_legal_params('C357_SALINA_1', 'C357_SALINA_2');
select pg_temp.clone_legal_params('C357_SALINA_1', 'C357_SALOBRA_1');

delete from public.parametro p
using public.legislacao_contexto c
where p.contexto_legislacao_id = c.id
  and c.codigo = 'C357_SALOBRA_1'
  and p.nome in ('Bário total', 'Tálio total', 'Urânio total');

select pg_temp.clone_legal_params('C357_SALOBRA_1', 'C357_SALOBRA_1_AQUICULTURA');
select pg_temp.clone_legal_params('C357_SALOBRA_1', 'C357_SALOBRA_2');

delete from public.parametro p
using public.legislacao_contexto c
where p.contexto_legislacao_id = c.id
  and c.codigo in ('C357_SALOBRA_1_AQUICULTURA', 'C357_SALOBRA_2')
  and p.nome in ('Bário total', 'Tálio total', 'Urânio total');

commit;
